Section CANSEC1. Context {rc : runConstT}.

(* [comment removed for export] *)
Definition small_res (hb n : Z) : Z := if (n <? 2^64 - 119) && (hb <? n) then -20 else n.

Section S.
  Variables (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (SP lo : Z).
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SPT : SP + 16 < KEND.
  Hypothesis LOS : lo <= SP - 176 - 4096.
  Hypothesis LOC : ATOP <= lo.
  Variable RNG : footprint.
  Hypothesis RSTK : rng RNG lo (SP - lo).
  Hypothesis RI : rng_aimg RNG.

  Lemma rd_small2G : forall (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x19 x20 x21 x22 x23 x27 x28 x29 x30 x31 : word) m (FF n hb : Z) (Q : machine_state -> Prop),
    rw_cells asegs m (Z.shiftr FF 3 + 2147450880) RFFSH0 -> mem_inv asegs m ->
    ablk FF (FF + 64) -> FF mod 64 = 0 -> rng RNG (shad FF) 8 ->
    0 <= n < 2^64 -> 0 <= hb < 8 ->
    (forall m' (y10 y12 : word),
        munch [(Z.shiftr FF 3 + 2147450880 + 4, Z.shiftr FF 3 + 2147450880 + 5)] m m' -> wmono asegs m m' -> mem_inv asegs m' ->
        rw_cells asegs m' (Z.shiftr FF 3 + 2147450880) RFFSH ->
        evtF asegs RNG Q
          (MS (mkR x1 (Z_to_bv 64 (SPAz SP)) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 (SPAz SP))
                   y10 (Z_to_bv 64 (small_res hb n)) y12 x13 x14 x15 x16 x17
                   (Z_to_bv 64 FF) x19 x20 x21 x22 (Z_to_bv 64 hb) x23 (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) x27 x28 x29 x30 x31)
              F (Z_to_bv 64 0x95004) fc None m' (seg_rom asegs))) ->
    evtF asegs RNG Q
      (MS (mkR x1 (Z_to_bv 64 (SPAz SP)) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 (SPAz SP))
               (Z_to_bv 64 n) x11 x12 x13 x14 x15 x16 x17
               (Z_to_bv 64 FF) x19 x20 x21 x22 (Z_to_bv 64 hb) x23 (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) x27 x28 x29 x30 x31)
          F (Z_to_bv 64 0x94adc) fc None m (seg_rom asegs)).
